export function exportRuntimeMarkdown(p){return memoPass(p,()=>exportRuntimeMarkdownOf(p));}
function exportRuntimeMarkdownOf(p){const m=p.runtime,label=id=>runtimeInput(p,id)?.ref||plan(p,id)?.ref||zone(p,id)?.ref||id;return '# AIW V5 · Deployment / runtime\n\n'+p.name+' · Working operating design. Locations, counts, and scenario outcomes are assumptions until reviewed. No resources are provisioned by this model.\n\n'+m.environments.map(e=>'## '+e.ref+' · '+e.title+'\n\n'+said(e.stage)+' · Owner: '+e.owner+'\n\n'+e.purpose+'\n\nScope: '+e.assetIds.map(label).join(', ')+'\n\nBasis: '+e.basis+' · '+(e.confirmed?'Reviewed':'Unconfirmed')+'\n\n'+zones(p,e.id).map(z=>'- '+z.ref+' · '+z.title+(z.kind?' · '+z.kind:'')+' · '+z.failureDomain+' · '+z.owner+(zoneBoundaries(z).length?' · holds '+zoneBoundaries(z).map(id=>p.technology.boundaries.find(b=>b.id===id)?.ref||id).join(', '):'')+'\n  '+z.isolation).join('\n')+'\n\n').join('')+'# Runtime plans\n\n'+plans(p).map(r=>{const s=runtimeSources(p,r),k=planCopies(p,r),q=planRequirements(p,r);return '## '+r.ref+' · '+r.title+'\n\n'+(runtimeIsSeed(p,r)?'Proposed by AIW when its environment was saved; not decided yet.\n\n':'')+'Asset: '+label(r.assetId)+' · '+environment(p,r.environmentId)?.ref+'\n\n'+[['purpose','Purpose'],['owner','Owner'],['releaseReference','Release/artifact reference'],['stateMode','State model'],['scalingPolicy','Scaling'],['readiness','Readiness and start-up'],['networkPolicy','Network access'],['monitoring','Monitoring and alerts'],['runbook','Runbook'],['rollout','Rollout'],['rollback','Rollback'],['recoveryStrategy','Recovery strategy'],['recoveryPlan','Recovery sequence'],['fencing','State/write authority'],['backupPlan','Protected copy'],['securityEnforcement','Security enforcement'],['assumptions','Assumptions']].map(([f,t])=>t+': '+r[f]).join('\n\n')+'\n\n'+planOperation(p,r).text+'\n\nRequirements it answers itself: '+(q.requirementIds.join(', ')||'none named')+(q.groups.length?' · groups '+q.groups.map(g=>g.id+' ('+g.members+')').join(', '):'')+(q.requirementIds.length||q.groups.length?' · delivery: '+deliveryOf(p,r).text:'')+'\n\nReplicas: '+k.text+' · '+r.capacityBasis+' · '+(r.capacityConfirmed?'Confirmed basis':'Assumption')+'\n\nRecovery time: '+(r.recoveryMinutes===''?'Unspecified':r.recoveryMinutes+' minutes')+' · Data loss: '+(r.lossMinutes===''?'Unspecified':r.lossMinutes+' minutes')+' · '+r.targetsBasis+' · '+(r.targetsConfirmed?'Confirmed basis':'Assumption')+'\n\nBackup location: '+(r.backupZoneId?label(r.backupZoneId):'Unspecified')+'\n\nControls: '+r.controlIds.map(id=>control(p,id)?.ref||id).join(', ')+'\n\nRequirements through its components: '+trailText(p,s.requirements.map(r=>r.id),s.applications)+'\n\nQuality drivers: '+s.drivers.map(r=>r.id).join(', ')+'\n\nDecisions: '+s.decisions.map(r=>r.id).join(', ')+'\n\n'+placements(p,r.id).map(l=>'- '+l.id+' · '+label(l.zoneId)+' · '+(l.role||'role not stated')+' · '+(stated(l.replicas)?l.replicas+' replicas':'replicas not stated')+' · '+l.basis).join('\n')+'\n\n';}).join('')+'# Runtime routes\n\n'+paths(p).map(r=>'- '+r.id+' · '+(c=>c?c.ref+' '+c.title+' ('+[c.from,c.to].map(id=>participantRef(p,id)).join(' → ')+')':'no contract')(contract(p,r.contractId))+' · '+environment(p,r.environmentId)?.ref+' · '+(r.mode||'dependency not stated')+(x=>x.boundaryIds.length?' · crosses '+x.boundaryIds.map(id=>p.technology.boundaries.find(b=>b.id===id)?.title||id).join(' and ')+(x.source==='path'?'':' (read from its contract)'):'')(pathCrossing(p,r))+(runtimeIsSeed(p,r)?' · proposed by AIW':'')+'\n  '+r.route+' · '+r.access+' · '+r.failureResponse).join('\n')+'\n\n# Review and exercise evidence\n\n'+m.evidence.map(e=>'- '+e.id+' · '+label(e.planId)+' · '+e.kind+' · '+e.result+' · '+(runtimeEvidenceCurrent(p,e)?'Current environment':'Earlier environment')+' · '+e.reviewer+' · '+e.reference+'\n  '+e.observations).join('\n')+'\n\nEvidence references are user-recorded and not independently verified by AIW.\n\n# Failure walkthroughs\n\n'+m.simulations.map(s=>'- '+s.id+' · '+s.mode+' · '+label(s.zoneId)+' · '+s.durationMinutes+' minutes · '+(s.withdrawn?'Withdrawn observation':runtimeSimulationCurrent(p,s)?'Current':'Earlier model')+'\n  '+s.observations+'\n  '+s.assessments.map(a=>a.driverId+': '+a.result+'; '+a.value+' '+a.unit+'; '+a.basis).join('\n  ')).join('\n')+'\n\nSimulations use declared replicas, dependencies, and recovery prerequisites. They do not prove live health, throughput, failover, provider availability, or financial consistency.\n\n# Review & realize handoff\n\n'+(runtimeHandoffCurrent(p)?'Current saved handoff':'Working preview; handoff needs review')+'\n\n'+runtimeFindings(p).map(f=>'- '+f.level+' · '+f.title+': '+f.detail).join('\n')+'\n';}
